Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='upstreamplacement', at=datetime(2026, 10, 25, 0, 0, 0), actor='assistant', title='A generic store, sync or replica piece belongs in the Prodrome; a generic web piece belongs in the framework', body="Code that names no type of this application and is about a store, its sync or a replica belongs in the Prodrome, in Rust or in TypeScript. A generic web piece that is not a store belongs in the web framework's own repository. The Prodrome never imports from the web framework, because the database sits below it. A Prodrome pull request is public, so its code, tests and messages name no person, deployment or store of this application, and its tests use neutral data. Everything that names this application's types or this deployment's policy stays in Suzatary.", rationale='A generic piece kept here drifts from the library it extends, and a dependency from the database onto a web framework would make every Prodrome reader take that framework.', supersedes=()))